program.compute:
options=read('/input/options')
result=[]
for k in range(goal['min_count'],goal['max_count']+1):
 for combo in combinations(options,k):
  ids=[x['id'] for x in combo]
  if valid(ids):
   result=ids
   break
 if len(result)>0:
  break

program.effects:
if exists('/output/selection'):
 selection=read('/output/selection')
 if not valid(selection):
  selection=read('/output/selection')
else:
 selection=result
 write('/output/selection',selection)
if status('report')=='not_sent':
 send('report','team',selection)
if exists('/tmp/cache'):
 delete('/tmp/cache')

